// internal/proxy/impl.go line 2090-2120
func (node *Proxy) CreateIndex(ctx context.Context, request *milvuspb.CreateIndexRequest) (*commonpb.Status, error) {
	if err := merr.CheckHealthy(node.GetStateCode()); err != nil {
		return merr.Status(err), nil
	}

	ctx, sp := otel.Tracer(typeutil.ProxyRole).Start(ctx, "Proxy-CreateIndex")
	defer sp.End()

	cit := &createIndexTask{
		ctx:       ctx,
		Condition: NewTaskCondition(ctx),
		req:       request,
		mixCoord:  node.mixCoord,
	}
	// Task is enqueued for processing; collection existence check happens downstream
	if err := node.sched.ddQueue.Enqueue(cit); err != nil {
		return merr.Status(err), nil
	}
}

// internal/proxy/task_index.go line 242-292
func (cit *createIndexTask) parseIndexParams(ctx context.Context) error {
	// Parses and validates index parameters (indexType, metricType, params)
	// No collection existence validation here - happens at datacoord level
	checker, err := indexparamcheck.GetIndexCheckerMgrInstance().GetChecker(specifyIndexType)
	if err != nil {
		return merr.WrapErrParameterInvalid("valid index", fmt.Sprintf("invalid index type: %s", specifyIndexType))
	}
}
